/* ========================================================== Brenda Anague: academic homepage (sidebar profile layout) Type: Newsreader (text, headings) + Instrument Sans (interface) Colour: burgundy = identity and the unknowns of the inverse problem blue = observed data ========================================================== */
@import url(“https://fonts.googleapis.com/css2?family=Instrument+Sans:wght@400;500;600&family=Newsreader:ital,opsz,wght@0,6..72,400..700;1,6..72,400..600&display=swap”);
:root { –ink: #22181d; –muted: #5f6168; –burgundy: #7e1635; –burgundy-deep: #5e1028; –observed: #2b4c7e; –page: #e4e7ec; /* backdrop behind the card. Alternatives: #1f2a44 navy, #4a0e20 deep burgundy, #e9e6e1 warm stone / –paper: #ffffff; –panel: #f7f8fa; –rule: #e2e4ea; –tint: #eef0f4; –side: 15.5rem; / width of the profile sidebar */
–serif: “Newsreader”, “Iowan Old Style”, Georgia, serif; –sans: “Instrument Sans”, system-ui, -apple-system, “Segoe UI”, sans-serif; }
/* ———- Page and card ———- */
body { font-family: var(–serif); font-size: 1.15rem; line-height: 1.65; color: var(–ink); background: var(–page); -webkit-font-smoothing: antialiased; }
#quarto-content { max-width: 1100px; width: calc(100% - 2rem); margin: 0 auto 4rem; padding: clamp(1.5rem, 5vw, 3.5rem); background: var(–paper); border-radius: 0 0 12px 12px; box-shadow: 0 30px 60px -40px rgba(20, 28, 48, 0.35); }
.quarto-title-block, #title-block-header { display: none; }
/* ———- Navbar: top strip of the card ———- */
body, body.nav-fixed { padding-top: 2rem !important; }
#quarto-header, #quarto-header.fixed-top { position: static; transform: none !important; transition: none; max-width: 1100px; width: calc(100% - 2rem); margin: 0 auto; background: var(–paper); border-radius: 12px 12px 0 0; }
body #quarto-header .navbar { background: transparent; border-bottom: 1px solid var(–rule); padding: 1.1rem 0; font-family: var(–sans); }
body #quarto-header .navbar-container { padding: 0 clamp(1.5rem, 5vw, 3.5rem); }
body #quarto-header .navbar-brand-container { margin-left: 0 !important; margin-right: auto !important; }
body .navbar .navbar-brand, body .navbar .navbar-brand .navbar-title { color: var(–ink); font-weight: 600; font-size: 1.1rem; letter-spacing: -0.01em; }
body .navbar .navbar-nav { margin-left: auto !important; margin-right: 0 !important; }
body .navbar .navbar-nav .nav-link { color: var(–muted); font-size: 0.85rem; font-weight: 500; letter-spacing: 0.05em; margin-left: 0.5rem; padding-left: 0.4rem; padding-right: 0.4rem; }
body .navbar .navbar-nav .nav-link:hover { color: var(–burgundy); }
body .navbar .navbar-nav .nav-link.active { color: var(–burgundy); box-shadow: inset 0 -2px 0 var(–burgundy); }
body .navbar .navbar-toggler { border-color: var(–rule); }
body .navbar .navbar-toggler-icon { background-image: url(“data:image/svg+xml,%3csvg xmlns=‘http://www.w3.org/2000/svg’ viewBox=‘0 0 30 30’%3e%3cpath stroke=‘%2322181d’ stroke-linecap=‘round’ stroke-miterlimit=‘10’ stroke-width=‘2’ d=‘M4 7h22M4 14h22M4 21h22’/%3e%3c/svg%3e”) !important; }
/* ———- Links ———- */
main.content a { color: var(–burgundy); text-decoration: underline; text-decoration-thickness: 1px; text-underline-offset: 0.2em; text-decoration-color: rgba(126, 22, 53, 0.35); }
main.content a:hover { color: var(–burgundy-deep); text-decoration-color: currentColor; }
main.content a:focus-visible { outline: 2px solid var(–burgundy); outline-offset: 3px; border-radius: 4px; }
/* ———- Two-column profile layout ———- */
.profile { display: grid; grid-template-columns: var(–side) minmax(0, 1fr); column-gap: clamp(2rem, 5vw, 3.5rem); align-items: start; }
/* ———- Sidebar ———- */
.profile-side { position: sticky; top: 1.5rem; }
.profile-photo figure, .profile-photo .quarto-figure { margin: 0; }
.profile-photo img { display: block; width: 100%; aspect-ratio: 4 / 5; object-fit: cover; object-position: center 25%; border-radius: 14px; border: 1px solid var(–rule); }
.profile-name { margin: 1.25rem 0 0.35rem; font-family: var(–serif); font-size: 2rem; font-weight: 500; line-height: 1.1; letter-spacing: -0.02em; color: var(–ink); }
.profile-role p, .profile-affil p { margin: 0; }
.profile-role p { font-family: var(–sans); font-size: 0.98rem; font-weight: 600; line-height: 1.4; color: var(–burgundy); margin-bottom: 0.5rem; }
.profile-affil p { font-family: var(–sans); font-size: 0.9rem; line-height: 1.5; color: var(–muted); }
.profile-links ul { margin: 1.25rem 0 0; padding: 0; list-style: none; }
.profile-links li { margin: 0; border-top: 1px solid var(–rule); }
.profile-links li:last-child { border-bottom: 1px solid var(–rule); }
main.content .profile-links a { display: flex; align-items: center; padding: 0.6rem 0.1rem; font-family: var(–sans); font-size: 0.93rem; font-weight: 500; color: var(–ink); text-decoration: none; }
main.content .profile-links a:hover { color: var(–burgundy); }
.profile-links i { width: 1.4rem; margin-right: 0.45rem; color: var(–burgundy); font-size: 1rem; }
/* ———- Main column ———- */
.flow p { margin: 0 0 1rem; }
.flow h2 { margin: 2.75rem 0 1rem; padding: 2rem 0 0; border: 0; border-top: 1px solid var(–rule); font-family: var(–serif); font-size: 1.6rem; font-weight: 600; line-height: 1.2; letter-spacing: -0.01em; color: var(–ink); }
.profile-main h2 { margin: 0 0 1rem; padding: 0; border: 0; }
/* ———- Publications ———- */
.flow .pub p:first-child { font-size: 1.2rem; line-height: 1.35; margin-bottom: 0.35rem; }
.flow .pub p + p { font-family: var(–sans); font-size: 0.95rem; color: var(–muted); }
/* ———- Current research ———- */
.focus { display: grid; grid-template-columns: repeat(auto-fit, minmax(15rem, 1fr)); gap: 1.75rem 2rem; }
.focus-item { padding-top: 1rem; border-top: 1px solid var(–rule); }
.flow .focus-item h3 { margin: 0 0 0.5rem; font-family: var(–serif); font-size: 1.3rem; font-weight: 600; letter-spacing: -0.01em; color: var(–ink); }
.flow .focus-item p { margin: 0; font-size: 1.05rem; line-height: 1.6; }
/* ———- Research interests ———- */
.flow .chips ul { display: flex; flex-wrap: wrap; gap: 0.55rem; margin: 0; padding: 0; list-style: none; }
.flow .chips li { margin: 0; padding: 0.4rem 0.85rem; border-radius: 999px; background: var(–tint); color: var(–burgundy-deep); font-family: var(–sans); font-size: 0.92rem; font-weight: 500; line-height: 1.3; }
/* ———- Education timeline ———- */
.flow .timeline { display: grid; grid-template-columns: repeat(auto-fit, minmax(20rem, 1fr)); column-gap: 2.5rem; }
.flow .timeline .tl-item p { display: grid; grid-template-columns: 5rem minmax(0, 1fr); column-gap: 1.25rem; margin: 0; padding: 0.9rem 0; border-top: 1px solid var(–rule); }
.tl-year { grid-column: 1; grid-row: 1 / span 2; padding-top: 0.25rem; font-family: var(–sans); font-size: 0.9rem; font-weight: 600; color: var(–burgundy); font-variant-numeric: tabular-nums; }
.tl-title { grid-column: 2; font-weight: 600; line-height: 1.3; }
.tl-place { grid-column: 2; font-size: 1rem; color: var(–muted); }
/* ———- Contact ———- */
.flow .contact ul { display: grid; grid-template-columns: repeat(auto-fit, minmax(16rem, 1fr)); gap: 1rem 2rem; margin: 0; padding: 0; list-style: none; }
.flow .contact li { display: grid; grid-template-columns: minmax(0, 1fr); row-gap: 0.1rem; padding-top: 0.75rem; border-top: 1px solid var(–rule); font-family: var(–sans); font-size: 0.98rem; overflow-wrap: anywhere; }
.c-label { color: var(–muted); font-size: 0.85rem; }
/* ———- Academic activities (academ.qmd) ———- */
/* first heading on the page: no divider above it */ .activities h2 { margin-top: 0; padding-top: 0; border-top: 0; }
.flow .note p { font-family: var(–sans); font-size: 0.95rem; color: var(–muted); margin: 0; }
.flow .activities h3 { margin: 2.25rem 0 0.5rem; font-family: var(–serif); font-size: 1.3rem; font-weight: 600; letter-spacing: -0.01em; color: var(–ink); }
.flow .events .tl-item p { display: grid; grid-template-columns: 7.5rem minmax(0, 1fr); column-gap: 1.5rem; margin: 0; padding: 0.85rem 0; border-top: 1px solid var(–rule); }
.events .tl-year { white-space: nowrap; }
.tag { display: inline-block; margin-left: 0.4rem; padding: 0.1rem 0.55rem; border-radius: 999px; background: var(–tint); color: var(–burgundy-deep); font-family: var(–sans); font-size: 0.75rem; font-weight: 600; vertical-align: 0.1em; }
/* ———- Mobile ———- */
@media (max-width: 820px) { .flow .events .tl-item p { grid-template-columns: minmax(0, 1fr); }
.events .tl-year, .events .tl-title, .events .tl-place { grid-column: 1; grid-row: auto; }
.profile { grid-template-columns: 1fr; row-gap: 2rem; }
.profile-side { position: static; }
.profile-photo { max-width: 200px; }
}
@media (prefers-reduced-motion: reduce) { * { transition: none !important; scroll-behavior: auto !important; } }
